INSERT INTO glossary_terms (term_key, term, aliases, definition, source, verified) VALUES
  ($g$hematuria$g$, $g$Hematuria$g$, ARRAY[$g$darah dalam urin$g$]::text[], $g$Adanya darah (sel darah merah) di dalam urin. Hematuria kasat mata membuat urin tampak merah muda, merah, atau cokelat. Hematuria mikroskopik tidak mengubah warna urin dan baru terdeteksi lewat mikroskop atau urinalisis.$g$, $g$NIDDK (NIH) — Hematuria (Blood in the Urine); diringkas ke bahasa Indonesia$g$, false),
  ($g$proteinuria$g$, $g$Proteinuria$g$, ARRAY[$g$protein dalam urin$g$]::text[], $g$Kelebihan protein darah di dalam urin. Kadar rendah masih normal, dan peningkatan sementara dapat terjadi, misalnya setelah olahraga atau saat sakit. Proteinuria yang menetap dapat menjadi tanda penyakit ginjal. Albuminuria adalah kelebihan albumin saja, sedangkan proteinuria mencakup berbagai protein.$g$, $g$Mayo Clinic — Protein in urine; diringkas ke bahasa Indonesia$g$, false),
  ($g$glomerulonefritis$g$, $g$Glomerulonefritis$g$, ARRAY[$g$GN$g$,$g$radang glomerulus$g$]::text[], $g$Peradangan pada glomerulus, yaitu unit penyaring kecil di ginjal. Peradangan yang berat atau berkepanjangan dapat merusak ginjal. Penyebabnya beragam, antara lain infeksi (misalnya pasca-streptokokus), penyakit autoimun, nefropati IgA, dan vaskulitis.$g$, $g$Mayo Clinic — Glomerulonephritis; NCBI MedGen (definisi HPO); diringkas ke bahasa Indonesia$g$, false),
  ($g$osteoporosis$g$, $g$Osteoporosis$g$, ARRAY[$g$keropos tulang$g$]::text[], $g$Penyakit tulang yang ditandai menurunnya kekuatan tulang sehingga risiko patah tulang meningkat. Kekuatan tulang ditentukan oleh massa tulang dan kualitas tulang. Penyakit ini sering tidak bergejala sampai terjadi patah tulang.$g$, $g$NIAMS (NIH) — Osteoporosis; diringkas ke bahasa Indonesia$g$, false),
  ($g$hipertensi$g$, $g$Hipertensi$g$, ARRAY[$g$tekanan darah tinggi$g$]::text[], $g$Keadaan ketika tekanan darah terlalu tinggi, menurut WHO yaitu 140/90 mmHg atau lebih. Diagnosis ditegakkan bila pada dua hari berbeda tekanan sistolik ≥140 mmHg dan/atau diastolik ≥90 mmHg. Sering tanpa gejala, sehingga satu-satunya cara mengetahuinya adalah mengukur tekanan darah. Ambang yang dipakai dapat berbeda antar pedoman.$g$, $g$WHO — Hypertension (fact sheet); diringkas ke bahasa Indonesia$g$, false)
